export const GARMIN_ICON_VIEW_BOX = "0 0 320 320";
export const GARMIN_ICON_TRANSFORM = "translate(0 256) scale(1 -1)";

const iconComponents = new Map();

export function garminActivityIcon(glyph) {
  if (!GARMIN_ACTIVITY_PATHS[glyph]) {
    throw new Error(`Unknown Garmin activity glyph: ${glyph}`);
  }
  if (!iconComponents.has(glyph)) {
    const Icon = forwardRef(function GarminActivityIcon(
      { size = 24, color = "currentColor", stroke: _stroke, title, ...props },
      ref,
    ) {
      return createElement(
        "svg",
        {
          ref,
          width: size,
          height: size,
          viewBox: GARMIN_ICON_VIEW_BOX,
          fill: color,
          stroke: "none",
          xmlns: "http://www.w3.org/2000/svg",
          "aria-hidden": title ? undefined : "true",
          focusable: "false",
          ...props,
        },
        title ? createElement("title", null, title) : null,
        createElement("path", {
          d: GARMIN_ACTIVITY_PATHS[glyph],
          transform: GARMIN_ICON_TRANSFORM,
        }),
      );
    });
    Icon.displayName = `GarminActivityIcon(${glyph})`;
    iconComponents.set(glyph, Icon);
  }
  return iconComponents.get(glyph);
}

export function garminActivityIconNode(glyph) {
  const path = GARMIN_ACTIVITY_PATHS[glyph];
  if (!path) throw new Error(`Unknown Garmin activity glyph: ${glyph}`);
  return [["path", { d: path, transform: GARMIN_ICON_TRANSFORM, key: glyph }]];
}
